pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    event PriceRequestAdded(bytes32 indexed identifier, uint256 time, bytes ancillaryData);

    function setUp() public { 
        c = new C(address(this));
    }

    function testRegression_property() public {
        // Call assertionDisputedCallback which triggers the internal logic.
        // In the reference, getAssertionPolicy returns arbitrateViaEscalationManager=false,
        // so the contract proceeds to call requestPrice and emits PriceRequestAdded.
        // In the bug, arbitrateViaEscalationManager=true, so requestPrice is never called.
        // We use vm.expectEmit to check that the event is emitted.
        vm.expectEmit(true, true, true, true);
        bytes32 identifier = keccak256("test");
        uint256 time = 123;
        bytes memory ancillaryData = "";
        emit PriceRequestAdded(identifier, time, ancillaryData);

        c.assertionDisputedCallback(bytes32(uint256(0xdeadbeef)));

        // If no revert and event was emitted (reference), test passes.
        // If event was not emitted (bug), test fails via vm.expectEmit mismatch.
        assertTrue(true);
    }
}

