pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testRegression_property() public {
        bytes32 assertionId = bytes32(uint256(1));
        // We need to simulate the OptimisticAsserter calling assertionDisputedCallback.
        // Since onlyOptimisticAsserter requires msg.sender == address(optimisticAsserter),
        // and the optimisticAsserter is set in constructor to address(this) (the test contract),
        // we can call directly.
        bool emitted = false;
        vm.expectEmit(true, true, true, true);
        emit PriceRequestAdded(keccak256(abi.encodePacked("default")), block.timestamp, "");
        // Capture whether the event was emitted by checking if the call succeeds.
        // However, we cannot catch events directly in Solidity; alternative: check the state change.
        // The buggy version does not emit PriceRequestAdded because arbitrateViaEscalationManager=true.
        // We can observe that by checking whether the call reverts.
        bool ok;
        try c.assertionDisputedCallback(assertionId) {
            ok = true;
        } catch {
            ok = false;
        }
        // In the reference, assertionDisputedCallback does not revert (it's a no-op), so ok = true.
        // In the buggy version, it also does not revert (since it just returns), so both pass.
        // But the event emission differs. However, we cannot directly assert events in the test (vm.expectEmit requires the event to be emitted).
        // Let's instead check the getAssertionPolicy return value to observe the difference.
        (bool blockAssertion, bool arbitrateViaEscalationManager, bool discardOracle, bool validateDisputers) = c.getAssertionPolicy(assertionId);
        assertTrue(arbitrateViaEscalationManager == false, "arbitrateViaEscalationManager should be false in reference");
    }
}

