import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testRegression_property() public {
        // Call assertionDisputedCallback with a concrete bytes32 value
        // The reference should revert (onlyOptimisticAsserter modifier requires msg.sender == optimisticAsserter)
        // The buggy version should not revert (modifier is no-op)
        bytes32 assertionId = bytes32(uint256(42));

        bool ok;
        try c.assertionDisputedCallback(assertionId) {
            ok = true;
        } catch {
            ok = false;
        }

        // The reference fails (ok == false) while the buggy one succeeds (ok == true)
        // We assert that the call reverts (ok == false), which holds for the reference but not the bug
        assertTrue(!ok);
    }
}

